  const entries=checked.entries.map(r=>({...r,id:crypto.randomUUID()})),batch={id:crypto.randomUUID(),name:s.name,actor:session.user.username,at:new Date().toISOString(),rows:structuredClone(entries)},next={...state,costs:[...state.costs,...entries],importBatches:[...(state.importBatches||[]),batch]};
