function masterView(){const unitAdmin=`<section class="card panel unit-admin"><h2>청구 단위 관리</h2><p class="sub">단위를 등록하면 기본 청구 단위·비용 입력·엑셀 양식에서 선택할 수 있습니다.</p><form id="billing-unit-form" class="master-add"><label>새 청구 단위<input name="unit" required maxlength="30" placeholder="예: 40FT, ROLL, 판"></label><button class="primary" type="submit">단위 등록</button></form><p id="billing-unit-error" class="settings-error" role="alert"></p><div class="unit-chips">${units.map(v=>`<span>${esc(v)}</span>`).join('')}</div></section>`;const parents=[...new Set(state.masters.map(m=>categoryParent(m.name)))];return unitAdmin+`<div class="card panel"><div class="panel-head"><div><h2>비용 항목 마스터</h2><div class="sub">대분류 아래 중분류 항목과 기본 청구 단위를 관리합니다.</div></div><span class="badge">사용 중 ${available().length}개</span></div><div class="notice">예: 보관·임차비 → 지급임차료 / 임가공비 → 임가공비(라벨링) / 포워딩 → 해상 운송료. 대분류는 직접 추가하거나 기존 이름을 선택하세요. 수출입 허용 비용 그룹을 지정하면 입력·엑셀에서 해당 그룹만 사용할 수 있습니다. 모두 해제하면 미분류만 허용합니다. 중분류 이름은 기존 입력·엑셀과 연결되므로 중복 등록할 수 없습니다. 분류 변경은 기존 내역의 조회 분류에도 적용되며 금액은 유지됩니다. 사용 제외한 항목은 신규 입력에서 제외되고 과거 분석에는 남습니다.</div><datalist id="category-parent-list">${parents.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist><form id="master-add" class="master-add"><label>대분류<input name="parentCategory" list="category-parent-list" required maxlength="40" placeholder="예: 포워딩"></label><label>중분류 항목명<input name="name" required maxlength="40" placeholder="예: 해상 운송료"></label>${selectField('unit','기본 청구 단위',units,'BOX')}<button class="primary" type="submit">＋ 항목 추가</button></form><p id="master-error" role="alert"></p><div class="table-wrap"><table><thead><tr><th>대분류</th><th>중분류</th><th>기본 청구 단위</th><th>수출입 허용 비용 그룹</th><th>상태</th><th>관리</th></tr></thead><tbody>${state.masters.map((m,i)=>`<tr><td><input data-master-parent="${i}" list="category-parent-list" value="${esc(categoryParent(m.name))}" maxlength="40" aria-label="${esc(m.name)} 대분류"></td><td>${esc(m.name)}</td><td><select data-master-unit="${i}" aria-label="${esc(m.name)} 기본 단위">${units.map(u=>`<option ${u===m.unit?'selected':''}>${u}</option>`).join('')}</select></td><td><details><summary>그룹 선택 (${categoryChargeGroups(m.name,state.masters).length})</summary><div class="charge-mapping">${chargeGroups.map(group=>`<label><input type="checkbox" data-master-charge="${i}" value="${esc(group)}" ${categoryChargeGroups(m.name,state.masters).includes(group)?'checked':''}>${esc(group)}</label>`).join('')}</div></details></td><td><span class="badge">${m.active?'사용 중':'사용 제외'}</span></td><td><button data-toggle-master="${i}">${m.active?'사용 제외':'다시 사용'}</button></td></tr>`).join('')}</tbody></table></div></div>`;}
function bindMasters(){
 $('#billing-unit-form').onsubmit=async e=>{e.preventDefault();const unit=String(new FormData(e.target).get('unit')).trim().toUpperCase();try{if(!validBillingUnit(unit))throw Error('청구 단위는 1~30자로 입력하세요.');if(units.some(v=>v.toUpperCase()===unit))throw Error('이미 등록된 청구 단위입니다.');await saveNext({...state,billingUnits:[...(state.billingUnits||[]),unit]});render();toast('청구 단위를 등록했습니다.');}catch(error){$('#billing-unit-error').textContent=error.message;}};

 document.querySelectorAll('[data-master-charge]').forEach(el=>el.onchange=async()=>{const i=Number(el.dataset.masterCharge),allowedChargeGroups=[...document.querySelectorAll('[data-master-charge="'+i+'"]:checked')].map(v=>v.value);try{await saveNext({...state,masters:state.masters.map((m,j)=>j===i?{...m,allowedChargeGroups}:m)});toast('항목별 허용 비용 그룹을 저장했습니다. 기존 내역은 유지됩니다.');}catch(error){$('#master-error').textContent=error.message;render();}});
 async function commit(next){try{await saveNext(next);return true;}catch(e){$('#master-error').textContent=e.message;return false;}}
 $('#master-add').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),name=String(data.get('name')).trim(),parentCategory=String(data.get('parentCategory')).trim(),unit=data.get('unit');if(!name||name.length>40||name==='all'||!validParentCategory(parentCategory)){$('#master-error').textContent='대분류와 중분류는 공백 제외 1~40자로 입력하세요.';return;}if(state.masters.some(m=>m.name.toLocaleLowerCase()===name.toLocaleLowerCase())){$('#master-error').textContent='이미 존재하는 중분류입니다. 기존 항목의 대분류를 변경하거나 다시 사용하세요.';return;}if(await commit({...state,masters:[...state.masters,{name,parentCategory,unit,active:true}]})){if(!categories.includes(name))categories.push(name);render();toast('대분류·중분류 항목을 추가했습니다.');}};
 document.querySelectorAll('[data-master-parent]').forEach(el=>el.onchange=async()=>{const i=Number(el.dataset.masterParent),parentCategory=el.value.trim();if(!validParentCategory(parentCategory)){$('#master-error').textContent='대분류는 공백 제외 1~40자로 입력하세요.';el.value=categoryParent(state.masters[i].name);return;}if(await commit({...state,masters:state.masters.map((m,j)=>j===i?{...m,parentCategory}:m)})){render();toast('대분류를 변경했습니다. 기존 비용 금액은 유지됩니다.');}else el.value=categoryParent(state.masters[i].name);});
 document.querySelectorAll('[data-toggle-master]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.toggleMaster);if(await commit({...state,masters:state.masters.map((m,j)=>j===i?{...m,active:!m.active}:m)})){render();toast('사용 상태를 변경했습니다. 기존 청구 내역은 유지됩니다.');}});
 document.querySelectorAll('[data-master-unit]').forEach(el=>el.onchange=async()=>{const i=Number(el.dataset.masterUnit);if(await commit({...state,masters:state.masters.map((m,j)=>j===i?{...m,unit:el.value}:m)}))toast('기본 청구 단위를 변경했습니다.');else render();});
}

function storeSelect(value,attrs,query=''){const selected=state.stores.find(s=>s.id===value),label=query||(selected?selected.code+' · '+selected.name:'');return `<div class="store-search"><input type="text" data-store-search list="store-search-options" autocomplete="off" placeholder="매장코드·매장명 검색 (빈 값: 센터 공통)" aria-label="매장 검색" value="${esc(label)}"><button type="button" data-store-common title="센터 공통으로 입력">공통</button><select class="store-source" tabindex="-1" aria-hidden="true" ${attrs}><option value="" ${!value?'selected':''}>센터 공통</option>${state.stores.filter(s=>s.active||s.id===value).map(s=>`<option value="${esc(s.id)}" ${s.id===value?'selected':''}>${esc(s.code)} · ${esc(s.name)}</option>`).join('')}</select></div>`;}
function closeStoreSearch(){if(!activeStoreSearch)return;activeStoreSearch.input.setAttribute('aria-expanded','false');activeStoreSearch.input.removeAttribute('aria-activedescendant');activeStoreSearch.popup.remove();activeStoreSearch=null;}
document.addEventListener('pointerdown',e=>{if(activeStoreSearch&&!activeStoreSearch.popup.contains(e.target)&&e.target!==activeStoreSearch.input)closeStoreSearch();},true);
function repositionStoreSearch(){if(!activeStoreSearch)return;const {input,popup}=activeStoreSearch;if(!input.isConnected){closeStoreSearch();return;}const rect=input.getBoundingClientRect();if(rect.bottom<=0||rect.top>=innerHeight){closeStoreSearch();return;}const width=Math.min(Math.max(rect.width,300),innerWidth-24);popup.style.width=width+'px';popup.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';popup.style.top='';popup.style.bottom='';if(innerHeight-rect.bottom<180&&rect.top>200){popup.style.bottom=innerHeight-rect.top+5+'px';popup.style.maxHeight=Math.min(300,rect.top-12)+'px';}else{popup.style.top=rect.bottom+5+'px';popup.style.maxHeight=Math.min(300,Math.max(140,innerHeight-rect.bottom-12))+'px';}}
window.addEventListener('resize',repositionStoreSearch);document.addEventListener('scroll',e=>{if(activeStoreSearch&&e.target!==activeStoreSearch.popup&&!activeStoreSearch.popup.contains(e.target))repositionStoreSearch();},true);
function bindStoreSearch(root,onPending){
 root.querySelectorAll('.store-search').forEach(box=>{const input=box.querySelector('[data-store-search]'),select=box.querySelector('select'),existingId=select.value;input.removeAttribute('list');input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-expanded','false');input.setAttribute('aria-controls','store-search-results');
 const choose=store=>{input.value=store.id?store.code+' · '+store.name:'';input.setCustomValidity('');if(![...select.options].some(o=>o.value===store.id))select.add(new Option(store.code+' · '+store.name,store.id));select.value=store.id;onPending?.(select,'');closeStoreSearch();select.dispatchEvent(new Event('input',{bubbles:true}));};
 const exact=()=>{try{choose(resolveStoreSearch(input.value,state.stores,{existingId}));}catch(error){input.setCustomValidity(error.message);onPending?.(select,input.value);}};
 const draw=()=>{closeStoreSearch();const matches=matchingStores(input.value,state.stores,{existingId}),common=!input.value.trim()||searchIncludes('센터 공통',input.value),options=[...(common?[{id:'',groupId:'',name:'센터 공통'}]:[]),...matches].slice(0,80),popup=document.createElement('div');popup.className='store-search-results';popup.id='store-search-results';popup.setAttribute('role','listbox');popup.setAttribute('aria-label','매장 검색 결과');
 options.forEach((store,i)=>{const option=document.createElement('button');option.type='button';option.tabIndex=-1;option.setAttribute('role','option');option.setAttribute('aria-selected',i===0?'true':'false');option.id='store-result-'+i;option.textContent=store.id?store.code+' · '+store.name:'센터 공통';option.addEventListener('pointerdown',e=>e.preventDefault());option.onclick=()=>choose(store);popup.append(option);});
 const status=document.createElement('p');status.textContent=options.length?`검색 ${matches.length+(common?1:0)}개${matches.length>80?' · 검색어를 더 입력하세요.':''}`:'검색 결과가 없습니다. 매장코드 또는 이름을 확인하세요.';popup.append(status);document.body.append(popup);const rect=input.getBoundingClientRect(),width=Math.min(Math.max(rect.width,300),innerWidth-24),height=Math.min(300,Math.max(140,innerHeight-rect.bottom-12));popup.style.width=width+'px';popup.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';popup.style.maxHeight=height+'px';if(innerHeight-rect.bottom<180&&rect.top>200){popup.style.bottom=innerHeight-rect.top+5+'px';popup.style.maxHeight=Math.min(300,rect.top-12)+'px';}else popup.style.top=rect.bottom+5+'px';
 activeStoreSearch={input,popup,options,index:0};input.setAttribute('aria-expanded','true');if(options.length)input.setAttribute('aria-activedescendant','store-result-0');};
 input.addEventListener('input',e=>{e.stopPropagation();onPending?.(select,input.value);try{resolveStoreSearch(input.value,state.stores,{existingId});input.setCustomValidity('');}catch(error){input.setCustomValidity(error.message);}draw();});input.addEventListener('focus',draw);
 input.addEventListener('change',e=>{e.stopPropagation();try{const match=resolveStoreSearch(input.value,state.stores,{existingId});choose(match);}catch(error){input.setCustomValidity(error.message);}});
 input.addEventListener('keydown',e=>{if(e.isComposing||e.keyCode===229)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(activeStoreSearch?.input!==input)draw();else{const a=activeStoreSearch;if(a.options.length)a.index=(a.index+(e.key==='ArrowDown'?1:-1)+a.options.length)%a.options.length;}const a=activeStoreSearch;a.popup.querySelectorAll('[role=option]').forEach((el,i)=>el.setAttribute('aria-selected',i===a.index?'true':'false'));const option=a.popup.querySelectorAll('[role=option]')[a.index];if(option){input.setAttribute('aria-activedescendant',option.id);option.scrollIntoView({block:'nearest'});}}else if(e.key==='Enter'){e.preventDefault();e.stopPropagation();if(activeStoreSearch?.input===input&&activeStoreSearch.options.length)choose(activeStoreSearch.options[activeStoreSearch.index]);else exact();}else if(e.key==='Escape'){e.preventDefault();closeStoreSearch();}});
 input.addEventListener('blur',()=>setTimeout(()=>{if(activeStoreSearch?.input===input&&!box.contains(document.activeElement))closeStoreSearch();},0));
 if(input.value)try{const matched=resolveStoreSearch(input.value,state.stores,{existingId});if(matched.id!==select.value)input.setCustomValidity('검색 결과에서 매장을 다시 선택하세요.');}catch(error){input.setCustomValidity(error.message);}
 box.querySelector('[data-store-common]').onclick=()=>choose({id:'',groupId:''});});
}

function refreshScopeFilters(){const selected=selectedFilter('store'),el=$('#store');el.multiple=true;el.innerHTML='<option value="all">전체 관리그룹 · 매장</option>';for(const scope of storeScopeOptions())el.add(new Option(scope.label,scope.key));restoreFilter('store',selected);}
function storesView(){return `<div class="card panel"><div class="panel-head"><div><h2>매장 마스터</h2><div class="sub">① 관리그룹 등록 → ② 매장 마스터 등록 → ③ 비용 입력·엑셀 양식 다운로드</div></div></div><div class="notice">매장코드·매장명·관리그룹·사용 상태를 이 화면에서 먼저 관리하세요. 매장을 직접 추가하거나 전용 엑셀 양식으로 일괄 등록할 수 있습니다. 기존 비용은 임의로 배분하지 않고 ‘센터 공통’으로 유지합니다. 관리그룹은 등록 시점의 소속을 청구 내역에 보관하므로, 매장 소속을 바꿔도 과거 비용의 그룹은 바뀌지 않습니다.</div><div class="toolbar store-import-toolbar"><button id="store-template">매장 엑셀 양식 다운로드</button><button id="store-upload" class="primary">매장 일괄 업로드</button><input type="file" id="store-file" accept=".xlsx,.csv" hidden><label class="store-import-option"><input type="checkbox" id="store-new-groups" ${stagedStoreImport?.allowNewGroups?'checked':''}> 미등록 관리그룹도 함께 생성</label></div><div id="store-import-preview">${storeImportPreview()}</div><form id="group-add" class="master-add"><label>관리그룹명<input name="name" maxlength="40" required placeholder="예: 해외영업 1팀"></label><button class="primary">＋ 관리그룹 추가</button></form><form id="store-add" class="master-add"><label>매장코드<input name="code" maxlength="20" pattern="[A-Za-z0-9_-]{1,20}" required placeholder="예: KR-SEOUL-001"></label><label>매장명<input name="name" maxlength="40" required placeholder="예: 강남점"></label><label>관리그룹<select name="groupId" required>${state.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></label><button class="primary">＋ 매장 추가</button></form><p id="store-error" role="alert"></p><div class="master-search"><label>매장 검색<input id="store-search" placeholder="매장코드 또는 매장명 검색"></label></div><div class="table-wrap"><table><thead><tr><th>매장코드</th><th>매장명</th><th>관리그룹</th><th>상태</th><th>관리</th></tr></thead><tbody>${state.stores.map((s,i)=>`<tr data-store-record="${i}"><td><b>${esc(s.code)}</b></td><td><input data-store-name="${i}" aria-label="${esc(s.name)} 매장명" value="${esc(s.name)}" maxlength="40" required></td><td><select data-store-group="${i}" aria-label="${esc(s.name)} 관리그룹">${state.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===s.groupId?'selected':''}>${esc(g.name)}</option>`).join('')}</select></td><td><span class="badge">${s.active?'사용 중':'사용 제외'}</span></td><td><button data-store-toggle="${i}">${s.active?'사용 제외':'다시 사용'}</button></td></tr>`).join('')}</tbody></table></div></div>`;}
function bindStores(){
 bindStoreImport();
 async function commit(next){try{await saveNext(next);state=next;refreshScopeFilters();render();return true;}catch(e){$('#store-error').textContent=e.message;return false;}}
 for(const type of ['group','store'])$('#'+type+'-add').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),name=String(data.get('name')).trim(),list=type==='group'?state.groups:state.stores;if(!name||name==='센터 공통'||list.some(r=>r.name.toLocaleLowerCase()===name.toLocaleLowerCase())){$('#store-error').textContent='비어 있거나 중복된 이름입니다. 다른 이름을 입력하세요.';return;}if(type==='group')commit({...state,groups:[...state.groups,{id:crypto.randomUUID(),name}]});else {const code=String(data.get('code')).trim().toUpperCase();if(!/^[A-Z0-9_-]{1,20}$/.test(code)||state.stores.some(s=>s.code.toUpperCase()===code)){$('#store-error').textContent='매장코드는 영문·숫자·하이픈·밑줄 1~20자로 중복 없이 입력하세요.';return;}commit({...state,stores:[...state.stores,{id:crypto.randomUUID(),code,name,groupId:data.get('groupId'),active:true}]});}};
 $('#store-search').oninput=e=>{const q=e.target.value.trim().toLocaleLowerCase();document.querySelectorAll('[data-store-record]').forEach(row=>{const s=state.stores[Number(row.dataset.storeRecord)];row.hidden=!searchIncludes(`${s.code} ${s.name}`,q);});};
 document.querySelectorAll('[data-store-name]').forEach(el=>el.onchange=async()=>{const i=Number(el.dataset.storeName),name=el.value.trim();if(!name||name==='센터 공통'||state.stores.some((s,j)=>j!==i&&s.name.toLocaleLowerCase()===name.toLocaleLowerCase())){$('#store-error').textContent='매장명은 비어 있거나 중복될 수 없습니다.';el.value=state.stores[i].name;return;}commit({...state,stores:state.stores.map((s,j)=>j===i?{...s,name}:s)});});
 document.querySelectorAll('[data-store-group]').forEach(el=>el.onchange=()=>commit({...state,stores:state.stores.map((s,i)=>i===Number(el.dataset.storeGroup)?{...s,groupId:el.value}:s)}));
 document.querySelectorAll('[data-store-toggle]').forEach(el=>el.onclick=()=>commit({...state,stores:state.stores.map((s,i)=>i===Number(el.dataset.storeToggle)?{...s,active:!s.active}:s)}));
}
function storeComparison(){const data=rows(),map=new Map();for(const r of data.filter(r=>r.recordType!=='count')){const id=(r.storeId||'')+'|'+(r.groupId||'');if(!map.has(id))map.set(id,{storeId:r.storeId,groupId:r.groupId,amount:0});map.get(id).amount+=Number(r.amount);}const total=sum(data);return `<section class="card panel store-comparison"><div class="panel-head"><div><h2>매장 · 관리그룹별 비용 비교</h2><div class="sub">선택 범위의 공급가액 · 저장 당시 소속 기준</div></div><span class="badge">${map.size}개 구분</span></div><div class="table-wrap"><table><thead><tr><th>매장</th><th>관리그룹</th><th>공급가액</th><th>선택 비용 비중</th></tr></thead><tbody>${[...map.values()].sort((a,b)=>b.amount-a.amount).map(r=>`<tr><td>${esc(storeName(r.storeId))}</td><td>${esc(groupName(r.groupId))}</td><td>₩${money(r.amount)}</td><td>${total?(r.amount/total*100).toFixed(1):'0.0'}%</td></tr>`).join('')}</tbody></table>${map.size?'':'<div class="empty">선택 범위의 청구 내역이 없습니다.</div>'}</div><div class="notice">매장·그룹 필터의 KPI는 같은 범위로 등록한 물동량·매출만 사용합니다. 미등록 시 건당 비용과 물류비율을 계산하지 않습니다. 전체 조회는 센터 공통 물동량·매출을 우선 사용하며, 없으면 매장 지표를 합산합니다.</div></section>`;}

function refreshCountries(){const selected=selectedFilter('country');$('#country').innerHTML='<option value="all">전체 국가</option>';state.countries.forEach(c=>$('#country').add(new Option(`${c.code} · ${c.name}`,c.code)));restoreFilter('country',selected);}
function locationsView(){return `<div class="card panel"><div class="panel-head"><div><h2>국가 · 물류센터 기준정보</h2><div class="sub">국가를 등록한 뒤 해외 물류센터를 연결하세요.</div></div></div><div class="notice">국가코드는 ISO 2자리 형식으로 입력하세요 (예: KR, VN, US). 기존 센터는 대한민국으로 초기 연결했습니다. 해외 센터도 현재는 원화(KRW)로 환산한 비용을 입력합니다. 국가와 통화·세율은 별개이며 환율이나 세금을 자동 계산하지 않습니다.</div><form id="country-add" class="master-add"><label>국가코드<input name="code" maxlength="2" pattern="[A-Za-z]{2}" placeholder="VN" required></label><label>국가명<input name="name" maxlength="40" placeholder="베트남" required></label><button class="primary">＋ 국가 등록</button></form><div class="table-wrap"><table><thead><tr><th>국가코드</th><th>국가명</th><th>연결 센터 수</th></tr></thead><tbody>${state.countries.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.name)}</td><td>${state.centerMasters.filter(m=>m.countryCode===c.code).length}</td></tr>`).join('')}</tbody></table></div><form id="center-add" class="master-add"><label>물류센터명<input name="name" maxlength="60" required placeholder="예: 호치민 물류센터"></label><label>국가<select name="countryCode">${countryOptions('KR')}</select></label><button class="primary">＋ 물류센터 등록</button></form><p id="location-error" role="alert"></p><div class="table-wrap"><table><thead><tr><th>물류센터</th><th>소속 국가</th></tr></thead><tbody>${state.centerMasters.map((c,i)=>`<tr><td>${esc(c.name)}</td><td><select data-center-country="${i}" aria-label="${esc(c.name)} 국가">${countryOptions(c.countryCode)}</select></td></tr>`).join('')}</tbody></table></div></div>`;}
function countryOptions(code){return state.countries.map(c=>`<option value="${esc(c.code)}" ${code===c.code?'selected':''}>${esc(c.code)} · ${esc(c.name)}</option>`).join('');}
function bindLocations(){
 async function commit(next){try{await saveNext(next);}catch(e){$('#location-error').textContent=e.message;return false;}state=next;for(const c of state.centerMasters)if(!centers.includes(c.name)){centers.push(c.name);$('#center').add(new Option(c.name,c.name));}refreshCountries();render();return true;}
 $('#country-add').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),code=String(d.get('code')).trim().toUpperCase(),name=String(d.get('name')).trim();if(!/^[A-Z]{2}$/.test(code)||!name||state.countries.some(c=>c.code===code||c.name===name)){$('#location-error').textContent='국가코드는 영문 2자리로, 코드·국가명은 중복 없이 입력하세요.';return;}commit({...state,countries:[...state.countries,{code,name}]});};
 $('#center-add').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),name=String(d.get('name')).trim(),countryCode=d.get('countryCode');if(!name||name==='all'||centers.includes(name)){$('#location-error').textContent='물류센터명은 공백이나 중복 없이 입력하세요.';return;}commit({...state,centerMasters:[...state.centerMasters,{name,countryCode}]});};
 document.querySelectorAll('[data-center-country]').forEach(el=>el.onchange=()=>commit({...state,centerMasters:state.centerMasters.map((c,i)=>i===Number(el.dataset.centerCountry)?{...c,countryCode:el.value}:c)}));
}

function unifiedEntryView(domain){if(domain==='center'&&!state.centerMasters.length)return '<section class="card panel"><h2>물류센터를 먼저 등록하세요</h2><p class="notice">관리자가 국가 · 물류센터 기준정보에서 물류센터를 등록한 뒤 비용·건수를 입력할 수 있습니다.</p></section>';
 const d=unifiedDrafts[domain] ||= {month:filters().month,center:centers[0],countryCode:state.countries[0].code,shipment:'',ciplNo:'',internalNo:'',direction:'수출',incoterm:'',cargoType:'',containerType:'',namedPlace:'',origin:state.countries[0].code,destination:state.countries[0].code,rows:[newUnifiedRow(domain)]};
 const context=domain==='center'?selectField('center','물류센터',centers,d.center):`<label>${domain==='trade'?'선적 국가':'비용 국가'}<select name="countryCode">${countryOptions(d.countryCode)}</select></label>`;
 return `<form id="unified-entry" data-domain="${domain}" class="card panel">${draftControls('entry:'+domain)}<div class="panel-head"><h2>${domainLabels[domain]} 입력</h2><span class="badge">${domain==='center'?'비용과 건수를 함께 입력':'센터 선택 불필요'}</span></div><div class="entry-context">${input('month',domain==='trade'?'선적 월':'비용 월','month',d.month)}${context}${domain==='trade'?input('shipment','수출입관리번호','text',d.shipment)+tradeReferenceFields(d)+selectField('direction','수출입 구분',['수출','수입'],d.direction)+tradeFieldOptions(d)+`<label>출발국<select name="origin">${countryOptions(d.origin)}</select></label><label>도착국<select name="destination">${countryOptions(d.destination)}</select></label>`:''}</div>${domain==='trade'?`<div id="trade-guidance">${tradeGuidanceView(d)}</div>`:''}<div class="notice">${domain==='center'?'건수는 단가 없이 입력합니다. 비용은 수량 × 단가 또는 금액 직접 입력을 선택하세요. 총비용÷수량으로 단가를 역산할 수도 있습니다. 역산 단가는 소수 여섯 자리까지 표시하고 입력 총비용을 그대로 저장합니다. 비용 행의 역산 수량은 출고 건수 KPI에 더하지 않습니다. 건수는 총비용에 자동 제외되며 B2C/B2B 증감 분석에 사용됩니다.':'수출입·공통 비용도 전체 비용에 포함됩니다. 외화는 입력 방식에서 ‘외화금액 × 환율’을 선택하세요. 환율은 외화 1/100/1000 단위당 원화로 직접 입력하며, 환산액만 총비용에 합산합니다. 다른 화면에 같은 비용을 중복 입력하지 마세요.'} 매장코드와 관리그룹은 마스터를 사용합니다.</div>${quickEntryView(domain)}<div class="table-wrap"><table class="entry-table"><thead><tr><th>#</th><th>유형</th><th>업무</th><th>매장</th><th>관리그룹</th><th>항목</th>${domain==='trade'?'<th>비용 그룹</th>':''}<th>입력 방식</th><th>단위</th><th>수량 / 건수</th><th>단가</th><th>총비용 / 금액</th>${domain==='trade'?'<th>외화·환율</th>':''}<th>메모</th><th></th></tr></thead><tbody>${d.rows.map((r,i)=>`<tr data-unified-row="${i}"><td>${i+1}${r.autoRecommended?'<small class="muted">자동</small>':''}</td><td><select data-u="recordType" aria-label="${i+1}행 유형"><option value="cost" ${r.recordType==='cost'?'selected':''}>비용</option>${domain==='center'?`<option value="count" ${r.recordType==='count'?'selected':''}>건수</option>`:''}</select></td><td>${rowSelect('account',['B2C','B2B','공통'],r.account,i)}</td><td>${storeSelect(r.storeId,`data-u="storeId" aria-label="${i+1}행 매장"`,r.storeQuery||'')}</td><td>${r.storeId?esc(groupName(state.stores.find(s=>s.id===r.storeId)?.groupId)):`<select data-u="groupId"><option value="">미지정</option>${state.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===r.groupId?'selected':''}>${esc(g.name)}</option>`).join('')}</select>`}</td><td>${r.recordType==='count'?'출고 건수 (자동)':rowSelect('category',available(),r.category,i)}</td>${domain==='trade'?`<td><select data-u="chargeGroup"><option value="">미분류</option>${categoryChargeGroups(r.category,state.masters).map(v=>`<option ${v===r.chargeGroup?'selected':''}>${v}</option>`).join('')}</select></td>`:''}<td><select data-u="mode" ${r.recordType==='count'?'disabled':''}><option value="calculated" ${r.mode==='calculated'?'selected':''}>수량 × 단가</option><option value="amount" ${r.mode==='amount'?'selected':''}>금액 직접</option><option value="reverse" ${r.mode==='reverse'?'selected':''}>총비용 ÷ 수량 (단가 역산)</option>${domain==='trade'?`<option value="fx" ${r.mode==='fx'?'selected':''}>외화금액 × 환율</option>`:''}</select></td><td>${r.recordType==='count'?'건':rowSelect('unit',units,r.unit,i)}</td><td>${unifiedNumber('quantity',r.quantity,i,['amount','fx'].includes(r.mode)&&r.recordType==='cost')}</td><td>${unifiedNumber('price',r.price,i,r.recordType==='count'||['amount','fx','reverse'].includes(r.mode))}</td><td>${unifiedNumber('amount',r.amount,i,r.recordType==='count'||!['amount','reverse'].includes(r.mode))}</td>${domain==='trade'?`<td>${rowForeignFields(r,i)}</td>`:''}<td><input data-u="memo" value="${esc(r.memo)}" maxlength="500"></td><td><button type="button" data-u-remove="${i}">✕</button></td></tr>`).join('')}</tbody></table></div><button type="button" id="unified-add" class="add-row">＋ 행 추가</button><div class="sheet-summary"><span>비용 합계 <b id="unified-cost"></b></span><span>출고 건수 <b id="unified-count"></b></span></div><p id="unified-error" role="alert"></p><div class="sheet-actions"><span class="muted">전체 행 검증 후 일괄 저장합니다. 저장 전 새로고침하면 입력이 사라집니다.</span><button class="primary" type="submit">일괄 저장</button></div></form>`;
}
function newUnifiedRow(domain='center'){const category=domain==='trade'&&available().includes('포워딩')?'포워딩':available()[0]||'';return {recordType:'cost',account:domain==='center'?'B2C':'공통',storeId:'',groupId:'',category,unit:defaultUnit(category),mode:'calculated',quantity:'',price:'',amount:'',memo:'',chargeGroup:'',currency:'KRW',foreignAmount:'',exchangeRate:'',rateBasis:1,rateDate:''};}
function rowSelect(field,list,value,i){return `<select data-u="${field}" aria-label="${i+1}행 ${field}">${field==='category'?groupedCategoryOptions(list,value):list.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`;}
function unifiedNumber(field,value,i,disabled){return `<input data-u="${field}" aria-label="${i+1}행 ${field}" type="number" min="0" max="1000000000000" step="${field==='amount'?'1':'0.001'}" value="${esc(value)}" ${disabled?'disabled':''}>`;}
function bindUnifiedEntry(){
 const form=$('#unified-entry'),domain=form.dataset.domain,d=unifiedDrafts[domain];
 bindStoreSearch(form,(select,query)=>{const i=Number(select.closest('[data-unified-row]').dataset.unifiedRow);if(query)d.rows[i].storeQuery=query;else delete d.rows[i].storeQuery;});bindQuickEntry(form,domain,d);
 bindDraftControls('entry:'+domain,()=>({kind:'entry',domain,draft:structuredClone(d)}),data=>{if(data.kind!=='entry'||data.domain!==domain||!Array.isArray(data.draft?.rows)||data.draft.rows.length>2000||data.draft.rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('입력 임시본 형식을 확인하세요.');unifiedDrafts[domain]=data.draft;render();});
 function refreshTradeGuidance(){if(domain==='trade'){$('#trade-guidance').innerHTML=tradeGuidanceView(d);bindTradeButtons();}}
 function focusCharge(group){const i=d.rows.findIndex(r=>r.chargeGroup===group),row=form.querySelector(`[data-unified-row="${i}"]`);if(!row)return;const field=row.querySelector(d.rows[i].mode==='fx'?'[data-u="foreignAmount"]':d.rows[i].mode==='amount'?'[data-u="amount"]':'[data-u="quantity"]');field?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});field?.focus({preventScroll:true});}
 function tradeCategoryForGroup(group){return ['포워딩',...available()].find(name=>available().includes(name)&&categoryChargeGroups(name,state.masters).includes(group));}
 function createChargeRow(group){const first=d.rows[0]||{};return {...newUnifiedRow('trade'),storeId:first.storeId||'',groupId:first.groupId||'',account:first.account||'공통',category:tradeCategoryForGroup(group)||'포워딩',chargeGroup:group,mode:'amount',unit:'일괄'};}
 function syncRecommendations(){if(domain!=='trade')return;const recommended=tradeGuidance(d).recommended;d.rows=syncRecommendedTradeRows(d.rows,chargeGroups.filter(group=>recommended.includes(group)&&tradeCategoryForGroup(group)),createChargeRow);if(!d.rows.length)d.rows=[newUnifiedRow('trade')];}
 function bindTradeButtons(){form.querySelectorAll('[data-add-charge]').forEach(b=>b.onclick=()=>{const group=b.dataset.addCharge;if(d.rows.some(r=>r.chargeGroup===group)){focusCharge(group);return;}if(!tradeCategoryForGroup(group)){toast('이 비용 그룹을 사용할 항목을 기준정보에서 지정하세요.');return;}const r=createChargeRow(group);r.manualEntry=true;if(d.rows.length===1&&!d.rows[0].manualEntry&&!d.rows[0].chargeGroup&&![d.rows[0].quantity,d.rows[0].price,d.rows[0].amount,d.rows[0].foreignAmount||'',d.rows[0].memo].some(v=>String(v).trim()))d.rows=[{...r,storeId:d.rows[0].storeId,groupId:d.rows[0].groupId,account:d.rows[0].account}];else d.rows.push(r);render();const i=d.rows.findIndex(r=>r.chargeGroup===group);const field=document.querySelector(`[data-unified-row="${i}"] [data-u="amount"]`);field?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});field?.focus({preventScroll:true});});}
 bindTradeButtons();
 function totals(){let cost=0,count=0;for(const r of d.rows){if(r.recordType==='count')count+=Number(r.quantity)||0;else try{cost+=r.mode==='fx'?convertForeignAmount(r.foreignAmount,r.exchangeRate,r.rateBasis):['amount','reverse'].includes(r.mode)?(Number(r.amount)||0):lineAmount(r.quantity,r.price);}catch{}}form.querySelectorAll('[data-unified-row]').forEach(el=>{const r=d.rows[Number(el.dataset.unifiedRow)];if(r.mode!=='reverse'||r.recordType==='count')return;try{r.price=reverseUnitPrice(r.quantity,r.amount);}catch{r.price='';}const field=el.querySelector('[data-u=price]');if(field){field.value=r.price;field.title='총비용 기준으로 계산한 단가 · 소수 여섯 자리';}});form.querySelectorAll('[data-fx-output]').forEach(el=>{const r=d.rows[Number(el.dataset.fxOutput)];try{el.textContent='₩'+money(convertForeignAmount(r.foreignAmount,r.exchangeRate,r.rateBasis));}catch{el.textContent='금액·환율 확인';}});$('#unified-cost').textContent='₩'+money(cost);$('#unified-count').textContent=money(count)+'건';}
 form.oninput=e=>{const field=e.target.dataset.u;if(field){const i=Number(e.target.closest('[data-unified-row]').dataset.unifiedRow);d.rows[i][field]=e.target.value;if(field==='storeId'&&!e.target.value)d.rows[i].groupId='';d.rows[i].autoRecommended=false;d.rows[i].manualEntry=true;if(field==='recordType'&&e.target.value==='count'&&d.rows[i].mode==='reverse')d.rows[i].mode='calculated';if(field==='mode'&&e.target.value==='fx'&&d.rows[i].currency==='KRW')d.rows[i].currency='';if(field==='category'){d.rows[i].unit=defaultUnit(e.target.value);if(domain==='trade'&&!categoryChargeGroups(e.target.value,state.masters).includes(d.rows[i].chargeGroup))d.rows[i].chargeGroup='';}if(field==='storeId'){const store=state.stores.find(s=>s.id===e.target.value),cell=e.target.closest('tr').querySelector('td:nth-child(5)');d.rows[i].groupId=store?.groupId||'';if(store)cell.textContent=groupName(store.groupId);else cell.innerHTML='<select data-u="groupId"><option value="">미지정</option>'+state.groups.map(g=>'<option value="'+esc(g.id)+'">'+esc(g.name)+'</option>').join('')+'</select>';totals();return;}if(['recordType','category','mode'].includes(field)){render();return;}}else if(e.target.name){d[e.target.name]=e.target.value;if(domain==='trade'&&['incoterm','direction'].includes(e.target.name)){syncRecommendations();render();return;}if(e.target.name==='cargoType'){if(d.cargoType!=='FCL')d.containerType='';render();return;}}totals();};
 $('#unified-add').onclick=async()=>{d.rows.push({...newUnifiedRow(domain),manualEntry:true});render();};
 document.querySelectorAll('[data-u-remove]').forEach(b=>b.onclick=async()=>{d.rows.splice(Number(b.dataset.uRemove),1);if(!d.rows.length)d.rows.push({...newUnifiedRow(domain),manualEntry:true});render();});
 form.onsubmit=async e=>{e.preventDefault();const entries=[];try{for(let i=0;i<d.rows.length;i++){const r=d.rows[i];if(![r.quantity,r.price,r.amount,r.foreignAmount??'',r.memo].some(v=>String(v).trim()))continue;try{entries.push(validateRecord({...d,...r,domain,rows:undefined},importContext()));}catch(err){throw Error(`${i+1}행: ${err.message}`);}}if(!entries.length)throw Error('한 행 이상 입력하세요.');assertNoNewCostDuplicates([...state.costs,...entries],state.costs);const next={...state,costs:[...state.costs,...entries.map(r=>({...r,id:crypto.randomUUID()}))]};if(!confirmFinancialSave(entries))return;await saveNext(next);state=next;}catch(err){$('#unified-error').textContent=err.message;return;}
 await clearSavedDraft('entry:'+domain);delete unifiedDrafts[domain];updateMonths();$('#month').value=d.month;for(const id of ['center','category','country','store','domain','account'])$('#'+id).value='all';view=domain==='trade'?'tradeReport':'costs';render();toast(`${entries.length}건을 저장했습니다. 건수는 비용 합계에서 제외됩니다.`);};totals();
}
function integratedSummary(){const rr=rows();return `<section class="card panel store-comparison"><h2>통합 비용 집계</h2><div class="kpis scope-summary">${Object.entries(domainLabels).map(([k,label])=>`<div><span>${label}</span><strong>₩${money(sum(rr.filter(r=>r.domain===k)))}</strong></div>`).join('')}<div><span>입력된 출고 건수 · 금액 제외</span><strong>${money(rr.filter(r=>r.recordType==='count').reduce((n,r)=>n+r.quantity,0))}건</strong></div></div><p class="muted">센터를 선택하면 해당 센터 자료만 조회됩니다. 수출입·공통비까지 보려면 전체 센터를 선택하세요. 건수는 금액 합계에 포함되지 않습니다.</p></section>`;}
function driverAnalysis(){const period=dashboardPeriod();return `<section class="card panel store-comparison"><h2>B2C · B2B 비용 증감 근거</h2><div class="notice">선택한 조회·비교 기간의 출고비와 건수로 평균 건당 비용 변화를 분해합니다. 비교 없는 YTD 모드에서는 증감 효과를 계산하지 않습니다. 실제 계약 단가나 증가 원인을 단정하지 않습니다. 출고비는 ‘B2C 출고비 / B2B 출고비’ 항목 기준이며, 건수는 해당 월·센터·매장 합계입니다.</div><div class="table-wrap"><table><thead><tr><th>업무</th><th>비교 기간 건수</th><th>조회 기간 건수</th><th>건당 비용(비교 → 조회)</th><th>건수 변화 효과</th><th>건당 비용 변화 효과</th><th>비용 증감 합계</th></tr></thead><tbody>${['B2C','B2B'].map(a=>{
 const selected=mo=>state.costs.filter(r=>r.domain==='center'&&dimensionMatch(r)&&countryMatch(r)&&scopeMatch(r)&&r.month===mo&&filterMatches('center',r.center));
 const now=period.current.flatMap(selected),old=period.previous.flatMap(selected),n=sum(now.filter(r=>r.category===a+' 출고비'&&categoryMatch(r.category))),p=sum(old.filter(r=>r.category===a+' 출고비'&&categoryMatch(r.category)));
 const count=rr=>countVolume(rr.filter(r=>r.account===a)),q=count(now),pq=count(old),complete=period.previous.length&&[...period.current,...period.previous].every(month=>{const rr=selected(month);return categoryMatch(a+' 출고비')&&count(rr)>0&&rr.some(r=>r.recordType!=='count'&&r.category===a+' 출고비');}),d=complete?costDrivers(n,p,q,pq):null;
 return `<tr><td>${a}</td><td>${money(pq)}건</td><td>${money(q)}건</td>${d?`<td>₩${money(d.oldRate)} → ₩${money(d.newRate)}</td><td>₩${money(d.volumeEffect)}</td><td>₩${money(d.rateEffect)}</td><td>₩${money(d.difference)}</td>`:'<td colspan="4">같은 범위의 조회·비교 기간의 건수가 필요합니다.</td>'}</tr>`;
 }).join('')}</tbody></table></div></section>`;}
function checkImport(lines,tab=costTab){let normalized;try{normalized=normalizeCostTabLines(lines,tab);}catch(e){return {entries:[],errors:[e.message]};}const result=validateImport(normalized,importContext());if(tab!=='all'&&result.entries.some(r=>r.domain!==tab))result.errors.push('현재 '+costTabLabels[tab]+' 탭과 다른 비용유형이 섞여 있습니다. 해당 탭 또는 전체 내역 탭을 사용하세요.');const seen=new Set(state.costs.map(fingerprint));for(let i=0;i<result.entries.length;i++){const r=result.entries[i],key=fingerprint(r);if(seen.has(key))result.errors.push(`검증 자료 ${i+1}번째: 동일 자료가 기존 내역 또는 파일 안에 있습니다. 중복 행을 제거하세요.`);seen.add(key);}return result;}

