 $('#backup-download').onclick=async()=>{try{const backup=await api('backup');downloadBlob(`물류비_전체백업_${new Date().toISOString().slice(0,10)}.json`,new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));toast('전체 자료 백업을 다운로드했습니다.');}catch(e){report(e);}};
