  'unit-cost':'<path d="m3 7 7-4 7 4-7 4-7-4Zm0 0v9l7 4 2-1m-2-8v9m7-13v4M6.5 5l7 4"/><circle cx="17" cy="17" r="5"/><path d="M18.5 15.5h-2a1 1 0 0 0 0 2h1a1 1 0 0 1 0 2h-2M17 14.5v6"/>',
